// ---------- 日月轮转素材：Codex 原图打包成图集（原版是 6 千万字节的 base64 脚本）----------
(function () {
  let meta = null, metaP = null; const pages = [], wpages = [], cut = {};
  const load = src => new Promise((ok, no) => { const im = new Image(); im.onload = () => ok(im); im.onerror = () => no(new Error('素材加载失败：' + src)); im.src = src; });
  const M = () => metaP || (metaP = fetch('ryx_assets/meta.json').then(r => r.json()).then(m => (meta = m)));
  const page = i => pages[i] || (pages[i] = load('ryx_assets/p' + i + '.webp'));
  const wpage = i => wpages[i] || (wpages[i] = load('ryx_assets/w' + i + '.webp'));
  window.RYX_IMG = async file => {
    await M();
    const m = file.match(/^assets\/v21\/white_(\d+)\.webp$/);
    if (m) { const e = meta.white[+m[1]]; const im = await wpage(e[0]); return { __white: e, im }; }   // 凝光序列：整页保留为图片（按需解码），不切成画布
    const k = meta.files[file]; if (!k) throw new Error('素材缺失：' + file);
    if (cut[k]) return cut[k];
    const [p, x, y, w, h] = meta.atlas[k], im = await page(p);
    const c = document.createElement('canvas'); c.width = w; c.height = h; c.getContext('2d').drawImage(im, x, y, w, h, 0, 0, w, h);
    return (cut[k] = c);
  };
  // 第 i 帧凝光：与原版 drawImage(frame, 0, 0) 同位置
  window.RYX_WHITE = (c, f) => { if (!f || !f.__white) return; const e = f.__white; c.drawImage(f.im, e[1], e[2], e[3], e[4], e[5], e[6], e[3], e[4]); };
})();

