 if(!openingPortraitV21Surface){openingPortraitV21Surface=document.createElement('canvas');openingPortraitV21Surface.width=1672;openingPortraitV21Surface.height=941;}
 const c=openingPortraitV21Surface.getContext('2d'),scale=g.w/1672,x=(620-g.x)/scale,y=(225-g.y)/scale,inner=115/scale,outer=180/scale;
 c.save();c.setTransform(1,0,0,1,0,0);c.globalAlpha=1;c.globalCompositeOperation='source-over';c.clearRect(0,0,1672,941);c.drawImage(eyePortrait(),0,0);
