 const m=c.createRadialGradient(x,y,inner,x,y,outer);m.addColorStop(0,'#fff');m.addColorStop(.25,'#ffffffed');m.addColorStop(.6,'#ffffff7f');m.addColorStop(1,'#ffffff00');c.fillStyle=m;c.fillRect(x-outer,y-outer,outer*2,outer*2);c.restore();
