 const L=introSurfaces(),scene=transformClear(L.scene);scene.drawImage(ctx.canvas,0,0,ctx.canvas.width,ctx.canvas.height,0,0,960,540);
 const light=V21_SOURCE_EYE.exposure(ms),st={day:light,sunrise:ms/6000,moon:0},handoff=1-Math.pow(1-clamp((ms-5950)/50),2);
 ctx.save();ctx.filter=`brightness(${.08+.78*light}) saturate(${.62+.38*light})`;ctx.drawImage(L.scene,0,0);ctx.filter='none';ctx.globalCompositeOperation='multiply';ctx.fillStyle=`rgba(23,43,91,${.43*(1-light)})`;ctx.fillRect(0,0,960,540);ctx.restore();
