  const q=ease((ms-start)/(end-start)),pass=Math.sin(clamp((ms-start)/(end-start+300))*Math.PI)*(1-moon);
  if(q<=0)continue;const light=transformClear(L.light);light.drawImage(L.scene,0,0);light.globalCompositeOperation='source-atop';light.fillStyle='rgba(255,211,126,.20)';light.fillRect(0,0,960,540);light.globalCompositeOperation='destination-in';
  const front=mix(1100,-220,q),g=light.createLinearGradient(front-180,0,front+240,0);g.addColorStop(0,'#ffffff00');g.addColorStop(.45,'#ffffffa0');g.addColorStop(.7,'#ffffff');g.addColorStop(1,'#ffffff00');light.fillStyle=g;light.fillRect(0,top,960,bottom-top);light.clearRect(0,0,960,top);light.clearRect(0,bottom,960,540-bottom);
  c.save();c.globalCompositeOperation='screen';c.globalAlpha=power*pass;c.drawImage(L.light,0,0);c.restore();
